create table veranolink.vl_types_environment (
    type_environment       varchar2(30 char),
    id_vl_type_environment number generated by default on null as identity minvalue 1 maxvalue 999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable
);

alter table veranolink.vl_types_environment
    add constraint vl_types_environment_pk primary key ( id_vl_type_environment )
        using index enable;


